  "techniques": [
    {
      "technique_id": "T1190",
      "technique_name": "Exploit Public-Facing Application",
      "evidence_quote": "The FBI observed Gunra actors obtaining initial access primarily through the exploitation of known vulnerabilities in internet-facing devices, including firewall and VPN appliances."
    },
    {
      "technique_id": "T1078.001",
      "technique_name": "Valid Accounts: Default Accounts",
      "evidence_quote": "KPNA observed that against one victim, Gunra actors gained access to an administrator account for a secure socket layer (SSL)-VPN appliance by exploiting default credentials"
    },
    {
      "technique_id": "T1106",
      "technique_name": "Native API",
      "evidence_quote": "Gunra’s Windows encryptor relies on native operating system (OS) application programming interfaces (APIs) to drive both execution and targeted encryption activity."
    },
    {
      "technique_id": "T1083",
      "technique_name": "File and Directory Discovery",
      "evidence_quote": "The binary uses the FindFirstFileW/FindNextFileW API calls to enumerate files and directories on all accessible drive letters (A through Z)"
    },
    {
      "technique_id": "T1021.002",
      "technique_name": "Remote Services: SMB/Windows Admin Shares",
      "evidence_quote": "Gunra actors regularly exploit Impacket libraries psexec.py and smbclient.py to move laterally across victim networks using the Server Message Block (SMB) protocol."
    },
    {
      "technique_id": "T1105",
      "technique_name": "Ingress Tool Transfer",
      "evidence_quote": "The actors subsequently downloaded OpenSSH (an SSH tunneling tool) from an external attacker-controlled server to establish connections between compromised systems and maintain persistence in the victim’s environment."
    },
    {
      "technique_id": "T1098",
      "technique_name": "Account Manipulation",
      "evidence_quote": "The actors modified the account configuration to bypass the mandatory password change requirement enforced on the account and subsequently leveraged it for malicious activities."
    },
    {
      "technique_id": "T1021.001",
      "technique_name": "Remote Services: Remote Desktop Protocol",
      "evidence_quote": "Using stolen session information, Gunra actors gained initial access to the internal virtual desktop infrastructure (VDI) environment and conducted lateral movement via RDP."
    },
    {
      "technique_id": "T1003.003",
      "technique_name": "OS Credential Dumping: NTDS",
      "evidence_quote": "Gunra actors using secretsdump.py (another Impacket library) to conduct OS credential dumping against compromised domain controllers to extract password hashes of user accounts from the NT Directory Services (NTDS) file."
    },
    {
      "technique_id": "T1550.004",
      "technique_name": "Use Alternate Authentication Material: Web Session Cookie",
      "evidence_quote": "The actors then used stolen session cookies to conduct session hijacking, impersonating legitimate users to gain access to the internal network."
    },
    {
      "technique_id": "T1556",
      "technique_name": "Modify Authentication Process",
      "evidence_quote": "the Gunra actors modified authentication processing files on the corporate VDI authentication portal server to allow successful authentication when a specific, Gunra-designated one time password (OTP) value was entered"
    },
    {
      "technique_id": "T1021.004",
      "technique_name": "Remote Services: SSH",
      "evidence_quote": "Additionally, the actors accessed a Hiware system access control server via SSH from a compromised virtual desktop"
    },
    {
      "technique_id": "T1070.003",
      "technique_name": "Indicator Removal: Clear Command History",
      "evidence_quote": "Gunra actors typically attempt to mask their presence by deleting system/network access logs and clearing command history."
    },
    {
      "technique_id": "T1622",
      "technique_name": "Debugger Evasion",
      "evidence_quote": "The Windows binary includes the IsDebuggerPresent API, which defends against reverse engineering by detecting if the application is being run in a debugger."
    },
    {
      "technique_id": "T1560.001",
      "technique_name": "Archive Collected Data: Archive via Utility",
      "evidence_quote": "For at least one known Gunra victim, the actors generated compressed archives with sensitive data and exfiltrated the archives to the file-sharing service Mega"
    },
    {
      "technique_id": "T1567.002",
      "technique_name": "Exfiltration Over Web Service: Exfiltration to Cloud Storage",
      "evidence_quote": "exfiltrated the archives to the file-sharing service Mega; the volume of exfiltrated data ranged up to tens of terabytes."
    },
    {
      "technique_id": "T1486",
      "technique_name": "Data Encrypted for Impact",
      "evidence_quote": "The binary achieves high speed file encryption of entire file systems by leveraging a multi-threaded architecture that supports parallel encryption of multiple files simultaneously"
    },
    {
      "technique_id": "T1490",
      "technique_name": "Inhibit System Recovery",
      "evidence_quote": "To increase the likelihood of ransom payment and prevent system recovery, Gunra actors also used Windows Management Instrumentation (WMI) to initiate deletion of volume shadow copies prior to encryption"
    },
    {
      "technique_id": "T1047",
      "technique_name": "Windows Management Instrumentation",
      "evidence_quote": "Gunra actors also used Windows Management Instrumentation (WMI) to initiate deletion of volume shadow copies prior to encryption"
    },
    {
      "technique_id": "T1136.001",
      "technique_name": "Create Account: Local Account",
      "evidence_quote": "create a new, malicious persistent user acct-vgapzwos with super user privileges and a hard-coded password."
    }
  ]
}
